import csv
import io
import json
import sys


def convert_csv(payload):
    """Convert CSV into string-valued records, or return invalid_input."""
    invalid = {"error": "invalid_input"}
    if not isinstance(payload, dict) or set(payload) != {"text", "delimiter"}:
        return invalid
    text = payload["text"]
    delimiter = payload["delimiter"]
    if not isinstance(text, str) or len(text) > 100000:
        return invalid
    if not isinstance(delimiter, str) or delimiter not in (",", ";", "\t"):
        return invalid

    try:
        with io.StringIO(text, newline="") as stream:
            reader = csv.reader(
                stream,
                delimiter=delimiter,
                quotechar='"',
                doublequote=True,
                skipinitialspace=False,
                strict=True,
            )
            headers = next(reader, None)
            if headers is None:
                return {"records": []}
            if not headers or len(headers) != len(set(headers)):
                return invalid

            records = []
            for row in reader:
                if len(row) != len(headers):
                    return invalid
                records.append(dict(zip(headers, row)))
            return {"records": records}
    except csv.Error:
        return invalid


def main():
    try:
        payload = json.load(sys.stdin)
    except (ValueError, UnicodeError):
        result = {"error": "invalid_input"}
    else:
        result = convert_csv(payload)
    json.dump(result, sys.stdout, ensure_ascii=True)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
